#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common Polybench definitions (NI, NJ, NK, NL, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for 2mm
#include "2mm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A, B, C, D in the same way as the original C version.
 *
 * C layout:
 *   A[ni][nk] -> Buffer A(k, i)  with shape (nk, ni)
 *   B[nk][nj] -> Buffer B(j, k)  with shape (nj, nk)
 *   C[nj][nl] -> Buffer C(l, j)  with shape (nl, nj)
 *   D[ni][nl] -> Buffer D(l, i)  with shape (nl, ni)
 */
static void init_array(int ni, int nj, int nk, int nl,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k"), l("l");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
    // A is stored as A(k, i) with shape (nk, ni)
    init_A(k, i) = cast<num_t>(((i * k + 1) % ni)) / cast<int>(ni);

    // B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / cast<int>(nj);

    // C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / cast<int>(nl);

    // D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<int>(nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // not used directly, but kept for symmetry

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C (simplified):
    //
    //   /* tmp = alpha * A * B */
    //   for (i)
    //     for (j) {
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //     }
    //
    //   /* D = beta * D + tmp * C */
    //   for (i)
    //     for (l) {
    //       D[i][l] *= beta;
    //       for (j)
    //         D[i][l] += tmp[i][j] * C[j][l];
    //     }
    //
    // Mapping to Halide coordinates (all Buffers are row‑major in the
    // first index, but we swap logical indices to keep the contiguous
    // dimension as the one we vectorize over):
    //
    //   i -> row index of A, tmp, D  (second Halide dimension)
    //   j -> column index of tmp     (first Halide dimension)
    //   k -> reduction index over NK (first dim of A_param, second of B_param)
    //   l -> column index of D       (first Halide dimension)
    //
    // Buffers:
    //   tmp(j, i)      corresponds to tmp[i][j]
    //   A_param(k, i)  corresponds to A[i][k]
    //   B_param(j, k)  corresponds to B[k][j]
    //   C_param(l, j)  corresponds to C[j][l]
    //   D_param(l, i)  corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // Stage 1: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
    // tmp(j, i) = tmp[i][j]
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // Stage 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
    // D(l, i) = D[i][l]
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goal:
    //   - Exploit cache locality via tiling over (i,j) and (i,l).
    //   - Parallelize over bands of rows i (coarse-grain parallelism).
    //   - Vectorize across the contiguous first dimension (j or l).
    //   - Keep memory footprint identical to the original (one full tmp).
    // ------------------------------------------------------------------------

    // Get a Target so we can choose a sensible natural vector width.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Reasonable tile sizes for a modern x64 CPU; these can be tuned.
    const int tile_i = 32;
    const int tile_j = 32;
    const int tile_l = 32;

    // ------------------------------
    // Schedule for tmp_func (A * B)
    // ------------------------------
    //
    // We treat tmp as a 2D matrix tmp(j, i) of shape (nj, ni).
    // We:
    //   - tile over (j, i) into (jo, io, ji, ii),
    //   - parallelize across io (bands of rows),
    //   - vectorize across ji (contiguous j),
    //   - in the update stage, iterate k_AB just outside ji so we can
    //     stream whole rows of B and tmp and keep A[i,k] in a scalar.

    tmp_func.compute_root();

    Var jo_tmp("jo_tmp"), io_tmp("io_tmp");
    Var ji_tmp("ji_tmp"), ii_tmp("ii_tmp");

    // Pure stage: initialize tmp(j, i) = 0 in tiles.
    tmp_func
        .tile(j, i,      // x, y
              jo_tmp, io_tmp,
              ji_tmp, ii_tmp,
              tile_j, tile_i)
        .parallel(io_tmp)           // different i-tiles in parallel
        .vectorize(ji_tmp, vec_width); // contiguous in j

    // Update stage: perform the reduction tmp += alpha*A*B
    tmp_func.update()
        .tile(j, i,
              jo_tmp, io_tmp,
              ji_tmp, ii_tmp,
              tile_j, tile_i)
        // Desired loop order inside a tile:
        //   for io_tmp (rows tile)
        //     for jo_tmp (cols tile)
        //       for ii_tmp (row inside tile)
        //         for k_AB (reduction over NK)
        //           for ji_tmp (vectorized cols inside tile)
        .reorder(ji_tmp, k_AB, ii_tmp, jo_tmp, io_tmp)
        .parallel(io_tmp)
        .vectorize(ji_tmp, vec_width);

    // ------------------------------
    // Schedule for D_func (tmp * C)
    // ------------------------------
    //
    // D_func(l, i) has shape (nl, ni).
    // We:
    //   - tile over (l, i) into (lo, io, li, ii),
    //   - parallelize across io (bands of rows),
    //   - vectorize across li (contiguous l),
    //   - in the update stage, iterate k_DC (over j) just outside li so
    //     that we take a scalar tmp[i,j] and apply it to vector rows of
    //     C[j,*] and D[i,*].

    D_func.compute_root();

    Var lo_D("lo_D"), io_D("io_D");
    Var li_D("li_D"), ii_D("ii_D");

    // Pure stage: scale D by beta in tiles.
    D_func
        .tile(l, i,
              lo_D, io_D,
              li_D, ii_D,
              tile_l, tile_i)
        .parallel(io_D)
        .vectorize(li_D, vec_width);

    // Update stage: D += tmp * C
    D_func.update()
        .tile(l, i,
              lo_D, io_D,
              li_D, ii_D,
              tile_l, tile_i)
        // Loop order inside a tile:
        //   for io_D (rows tile)
        //     for lo_D (cols tile)
        //       for ii_D (row inside tile)
        //         for k_DC (reduction over NJ)
        //           for li_D (vectorized cols inside tile)
        .reorder(li_D, k_DC, ii_D, lo_D, io_D)
        .parallel(io_D)
        .vectorize(li_D, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
