    // B[k][j] = (DATA_TYPE) (k*(j+1) % nj) / nj;
    // B is stored as B(j, k) with shape (nj, nk)
    init_B(j, k) = cast<num_t>(((k * (j + 1)) % nj)) / cast<int>(nj);

    // C[j][l] = (DATA_TYPE) ((j*(l+3)+1) % nl) / nl;
    // C is stored as C(l, j) with shape (nl, nj)
    init_C(l, j) = cast<num_t>(((j * (l + 3) + 1) % nl)) / cast<int>(nl);

    // D[i][l] = (DATA_TYPE) (i*(l+2) % nk) / nk;
    // D is stored as D(l, i) with shape (nl, ni)
    init_D(l, i) = cast<num_t>(((i * (l + 2)) % nk)) / cast<int>(nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;

    // Scalar parameters
    num_t alpha;
    num_t beta;

    // Buffers corresponding to the C arrays:
    //
    // A[ni][nk] -> A(k, i)
    // B[nk][nj] -> B(j, k)
    // C[nj][nl] -> C(l, j)
    // D[ni][nl] -> D(l, i)
    // tmp[ni][nj] -> tmp(j, i)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nl, nj);
    Halide::Buffer<num_t, 2> D(nl, ni);
    Halide::Buffer<num_t, 2> tmp(nj, ni);  // host-side buffer (not explicitly used by the pipeline)

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize data (equivalent to init_array in the C version)
    init_array(ni, nj, nk, nl, &alpha, &beta, A, B, C, D);

    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j) {
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //     }
    //
    //   for (i)
    //     for (l) {
    //       D[i][l] *= beta;
    //       for (j)
    //         D[i][l] += tmp[i][j] * C[j][l];
    //     }
    //
    // Mapping to Halide coordinates (to keep contiguous dimensions innermost):
    //   i -> row index  (second dimension)
    //   j -> column index for tmp and D (first dimension)
    //   k -> reduction index over nk     (A/B shared dimension)
    //   l -> column index of C and D     (first dim of C/D)
    //
    // Buffers:
    //   tmp(j, i)        corresponds to tmp[i][j]
    //   A_param(k, i)    corresponds to A[i][k]
    //   B_param(j, k)    corresponds to B[k][j]
    //   C_param(l, j)    corresponds to C[j][l]
    //   D_param(l, i)    corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj (j dimension)

    Func tmp_func("tmp");
    Func D_func("D");

    // Stage 1: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
    // -> tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // Stage 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
    // -> D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goal:
    //   - Exploit cache locality and SIMD on the contiguous dimensions:
    //       * j is the contiguous dimension of tmp and B.
    //       * l is the contiguous dimension of D and C.
    //   - Parallelize across rows (i) since each row is independent.
    //   - Keep the mathematical algorithm identical:
    //       tmp = alpha * A * B
    //       D   = beta * D + tmp * C
    //
    // We use:
    //   - For tmp update: loop order (i, k_AB, j) so that for each row i and
    //     reduction index k_AB, we stream over contiguous j in B and tmp.
    //   - For D update: loop order (i, k_DC, l) so that for each row i and j
    //     we stream across contiguous l in C and D.
    //   - Parallelization over i.
    //   - Vectorization over j (tmp/B) and l (D/C) using the target's
    //     natural vector width for the given element type.
    // ------------------------------------------------------------------------

    // Query the host target to choose a reasonable SIMD width
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;  // Fallback: no vectorization if unsupported
    }

    // ---------- Stage 1: tmp = alpha * A * B ----------

    // Compute tmp at root so it is fully available for the second stage,
    // matching the original C algorithm structure.
    tmp_func.compute_root();

    // Pure definition: initialization tmp(j,i) = 0
    //
    // Loop order: outer over i (rows), inner over j (columns).
    // Vectorize over j because tmp and B are contiguous in j.
    tmp_func
        .reorder(j, i)          // loops: for i { for j { ... } }
        .parallel(i)            // different rows in parallel
        .vectorize(j, vec_width);

    // Update definition: reduction over k_AB
    //
    // We prefer the loop nest:
    //   for i (parallel)
    //     for k_AB
    //       for j (vectorized)
    //
    // This reuses A(i,k_AB) across all columns j in tmp's row i, and
    // streams through contiguous B(j,k_AB) and tmp(j,i).
    tmp_func.update()
        .reorder(j, k_AB, i)    // arguments from innermost to outermost:
                                //   -> for i { for k_AB { for j { ... } } }
        .parallel(i)
        .vectorize(j, vec_width);

    // ---------- Stage 2: D = beta * D + tmp * C ----------

    // Compute D at root as the final output buffer, just like the C code.
    D_func.compute_root();

    // Pure definition: D(l, i) = beta * D_param(l, i)
    //
    // Loop order: for i (parallel) { for l (vectorized) }.
    // This keeps rows of D in cache and uses SIMD across contiguous l.
    D_func
        .reorder(l, i)          // loops: for i { for l { ... } }
        .parallel(i)
        .vectorize(l, vec_width);

    // Update definition: D(l, i) += tmp(k_DC, i) * C(l, k_DC)
    //
    // Desired loop order:
    //   for i (parallel)
    //     for k_DC  // j dimension
    //       for l (vectorized)
    //
    // so that:
    //   - tmp(k_DC, i) is a scalar reused across the l-loop.
    //   - C(l, k_DC) and D(l, i) are both contiguous in l.
    D_func.update()
        .reorder(l, k_DC, i)    // arguments from innermost to outermost:
                                //   -> for i { for k_DC { for l { ... } } }
        .parallel(i)
        .vectorize(l, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    // Compile the pipeline for the chosen target once, outside the timed region.
    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
