    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (l)
    //       D[i][l] *= beta;
    //       for (j)
    //         D[i][l] += tmp[i][j] * C[j][l];
    //
    // Mapping to Halide coordinates for storage chosen above:
    //   i -> row index of A and D (second dimension in A, D, tmp)
    //   j -> column index of tmp and D*C inner dimension
    //        (first dimension in tmp, C, B)
    //   k -> reduction index over nk (shared between A and B)
    //   l -> column index of C and D (first dimension in C, D)
    //
    // Buffers:
    //   tmp(j, i)    corresponds to tmp[i][j]
    //   A_param(k,i) corresponds to A[i][k]
    //   B_param(j,k) corresponds to B[k][j]
    //   C_param(l,j) corresponds to C[j][l]
    //   D_param(l,i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // Stage 1: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
    // as tmp(j, i) in our storage layout.
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // Stage 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
    // as D(l, i) in our storage layout.
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Goals:
    //   * Exploit data-parallelism: parallelize over rows i.
    //   * Exploit SIMD: vectorize along the contiguous dimension of each
    //     computation:
    //       - For tmp: contiguous in j (dimension 0 of tmp, B).
    //       - For D:   contiguous in l (dimension 0 of D, C).
    //   * Keep the algorithm identical while improving throughput.
    //
    // We deliberately keep the schedule relatively simple to ensure
    // correctness across arbitrary NI, NJ, NK, NL while still gaining
    // substantial speedups on a 32-core x64 CPU.
    // ------------------------------------------------------------------------

    // Choose a reasonable vector width based on element type.
    // For typical Polybench settings, DATA_TYPE is float or double.
    int vec_width;
    if (sizeof(num_t) == sizeof(float)) {
        vec_width = 8;   // 8-wide float vectors (AVX2, 256-bit)
    } else if (sizeof(num_t) == sizeof(double)) {
        vec_width = 4;   // 4-wide double vectors (AVX2, 256-bit)
    } else {
        // Fallback: no vectorization for unusual element sizes.
        vec_width = 1;
    }

    // ---- Stage 1: tmp = alpha * A * B ----

    // Compute tmp at root so it can be reused by the second stage.
    tmp_func.compute_root();

    // Pure definition (initialization to zero):
    //
    //   for i in [0, ni)
    //     for j in [0, nj)
    //       tmp(j, i) = 0;
    //
    // We want j (the contiguous dimension) innermost and vectorized,
    // and rows i processed in parallel.
    tmp_func
        .reorder(j, i)          // inner j, outer i
        .parallel(i)            // distribute rows across cores
        .vectorize(j, vec_width);

    // Update definition (reduction over k_AB):
    //
    //   for i in [0, ni)
    //     for j in [0, nj)
    //       for k_AB in [0, nk)
    //         tmp(j, i) += alpha * A(k_AB, i) * B(j, k_AB);
    //
    // Reorder so that j is innermost (for SIMD) and i is outermost (for
    // parallelism); keep the reduction variable innermost among scalar
    // loops so each lane accumulates a full dot product.
    tmp_func.update()
        .reorder(j, k_AB, i)    // loops: i (outer), k_AB, j (innermost)
        .parallel(i)
        .vectorize(j, vec_width);

    // ---- Stage 2: D = beta * D + tmp * C ----

    // Compute D at root; this is the final output.
    D_func.compute_root();

    // Pure definition (scaling D by beta):
    //
    //   for i in [0, ni)
    //     for l in [0, nl)
    //       D(l, i) = beta * D(l, i);
    //
    // We want l (contiguous dimension in D and C) innermost and
    // vectorized, and rows i in parallel.
    D_func
        .reorder(l, i)          // inner l, outer i
        .parallel(i)
        .vectorize(l, vec_width);

    // Update definition (accumulation of tmp * C into D):
    //
    //   for i in [0, ni)
    //     for l in [0, nl)
    //       for k_DC in [0, nj)
    //         D(l, i) += tmp(k_DC, i) * C(l, k_DC);
    //
    // As above, make l innermost for SIMD, i outermost for parallelism.
    D_func.update()
        .reorder(l, k_DC, i)    // loops: i (outer), k_DC, l (innermost)
        .parallel(i)
        .vectorize(l, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    // Compile the whole pipeline (both stages) to machine code.
    D_func.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D (in-place update of D_param).
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
