    // Bind buffers to ImageParams
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------------
    // Halide definition of the 2mm kernel:
    //
    // Original C:
    //   /* D := alpha*A*B*C + beta*D */
    //   for (i)
    //     for (j)
    //       tmp[i][j] = 0;
    //       for (k)
    //         tmp[i][j] += alpha * A[i][k] * B[k][j];
    //
    //   for (i)
    //     for (l)
    //       D[i][l] *= beta;
    //       for (j)
    //         D[i][l] += tmp[i][j] * C[j][l];
    //
    // Mapping to Halide coordinates:
    //   i -> row index  (second dimension of A, D, tmp)
    //   j -> column index of tmp and reduction index in second GEMM
    //   k -> reduction index in first GEMM (nk)
    //   l -> column index of C and D
    //
    // Buffers:
    //   tmp(j, i)    corresponds to tmp[i][j]
    //   A_param(k,i) corresponds to A[i][k]
    //   B_param(j,k) corresponds to B[k][j]
    //   C_param(l,j) corresponds to C[j][l]
    //   D_param(l,i) corresponds to D[i][l]
    // ------------------------------------------------------------------------

    Var i("i"), j("j"), l("l");
    RDom k_AB(0, A_param.dim(0).extent(), "k_AB");   // reduction over nk
    RDom k_DC(0, C_param.dim(1).extent(), "k_DC");   // reduction over nj

    Func tmp_func("tmp");
    Func D_func("D");

    // Stage 1: tmp[i][j] accumulation: tmp(j, i)
    tmp_func(j, i) = cast<num_t>(0);
    tmp_func(j, i) += Expr(alpha) * A_param(k_AB, i) * B_param(j, k_AB);

    // Stage 2: D[i][l] update: D(l, i)
    D_func(l, i) = Expr(beta) * D_param(l, i);
    D_func(l, i) += tmp_func(k_DC, i) * C_param(l, k_DC);

    // ------------------------------------------------------------------------
    // Scheduling
    //
    // Strategy (aligned with the optimized models, but kept simple and robust):
    //
    //  - Treat the kernel as two GEMMs:
    //       tmp  = alpha * A * B        (NI x NK) * (NK x NJ) -> NI x NJ
    //       D    = beta * D + tmp * C   (NI x NJ) * (NJ x NL) -> NI x NL
    //
    //  - For each stage:
    //      * compute at root so we have full control over parallelism.
    //      * parallelize outer loop over 'i' (rows): rows are independent.
    //      * vectorize over the contiguous dimension:
    //          - j in tmp_func  (tmp and B contiguous along j)
    //          - l in D_func    (D and C contiguous along l)
    //
    //  This improves data locality and SIMD utilization significantly
    //  compared to the purely serial, unvectorized baseline.
    // ------------------------------------------------------------------------

    // Choose a natural SIMD width for the current target and value type.
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());

    // --------------------
    // Stage 1: tmp_func
    // --------------------
    //
    // Layout:
    //   tmp(j, i): j is the stride‑1 dimension (x)
    //   B(j, k)  : j is stride‑1
    //   A(k, i)  : k is stride‑1 (good reuse across j)
    //
    // We want innermost loops over j to get contiguous SIMD loads/stores
    // for tmp and B, and good reuse of A(k,i) across all j for fixed (i,k).

    tmp_func
        .compute_root()
        // Default loop order for tmp(j,i) at root is: for i (outer), for j (inner).
        // Parallelize across rows (i): each row of tmp is independent.
        .parallel(i)
        // Vectorize across j (stride‑1 dimension of tmp and B).
        .vectorize(j, vec_width);

    tmp_func.update()
        // Reorder update loops to: for i (outer), for k_AB (middle), for j (inner).
        // This corresponds to:
        //   for i
        //     for k_AB
        //       for j
        //         tmp(i,j) += alpha * A(i,k_AB) * B(k_AB,j);
        //
        // which uses:
        //   - j innermost (contiguous in tmp and B) for SIMD,
        //   - A(i,k_AB) reused across all j, and
        //   - k_AB as a middle loop giving good streaming in A.
        .reorder(j, k_AB, i)
        .parallel(i)
        .vectorize(j, vec_width);

    // --------------------
    // Stage 2: D_func
    // --------------------
    //
    // Layout:
    //   D(l, i): l is stride‑1 (x dimension)
    //   C(l, j): l is stride‑1
    //   tmp(j,i): j is reduction dim
    //
    // We want innermost loops over l to get contiguous SIMD loads/stores
    // for D and C, and good reuse of tmp(j,i) across all l for fixed (i,j).

    D_func
        .compute_root()
        // Ensure pure loops order: for i (outer), for l (inner)
        .reorder(l, i)
        .parallel(i)
        .vectorize(l, vec_width);

    D_func.update()
        // Reorder update loops to: for i (outer), for k_DC (j) (middle),
        // for l (inner). This corresponds to:
        //   for i
        //     for k_DC (j)
        //       for l
        //         D(i,l) += tmp(i,k_DC) * C(k_DC,l);
        //
        // which uses:
        //   - l innermost (contiguous in D and C) for SIMD,
        //   - tmp(i,k_DC) reused across all l, and
        //   - k_DC as a middle loop giving good streaming in tmp.
        .reorder(l, k_DC, i)
        .parallel(i)
        .vectorize(l, vec_width);

    // ------------------------------------------------------------------------
    // JIT compile and run
    // ------------------------------------------------------------------------

    D_func.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: result is written into D
    D_func.realize(D);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix, similar to print_array in C.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // D(ii, jj) in C is D(l = jj, i = ii) in Halide
                std::cerr << D(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
